package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.RuntimeIntStore;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** Position feedback sensor with velocity/error/trajectory diagnostics for an adjacent servo. */
public class ServoPositionSensorBlock extends PassiveDirectionalSignalBlock{public ServoPositionSensorBlock(Properties p){super(p);}@Override public MapCodec<ServoPositionSensorBlock> codec(){return RedstoneEngineering.SERVO_POSITION_SENSOR_CODEC.value();}@Override protected int computeOutput(Level l,BlockPos p,BlockState s){BlockPos in=inputPos(p,s);if(!(l.getBlockState(in).getBlock() instanceof ServoActuatorBlock))return 0;return RuntimeIntStore.get(l,"servo",in,13)[0];}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){BlockPos in=inputPos(p,s);if(l.getBlockState(in).getBlock() instanceof ServoActuatorBlock){int[]r=RuntimeIntStore.get(l,"servo",in,13);pl.displayClientMessage(Component.literal("Servo feedback | position="+r[0]+" velocity="+r[2]+" error="+r[3]+" target="+r[1]+" settle="+r[11]+"t commands="+r[6]),true);}else pl.displayClientMessage(Component.literal("Servo position sensor | NO SERVO on BACK"),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}
